#!/usr/bin/env python3
"""Current 0.8.5 candidate guidance; keep historical candidates and stable APK."""
from pathlib import Path
import re
import struct
ROOT=Path(__file__).resolve().parents[1]; D=ROOT/'docs'
shell=(D/'preview-084.html').read_text()
head=re.sub(r'<!-- preview-08[345]:start -->.*?<!-- preview-08[345]:end -->','',shell[:shell.index('<main')],flags=re.S)
head=head.replace('0.8.4','0.8.5').replace('preview-084.html','preview-085.html')
foot=shell[shell.index('<footer'):]
body='''<main id="main" tabindex="-1"><section class="section wrap preview-intro"><p class="eyebrow">Android candidate · 0.8.5</p><h1>MeBot 0.8.5</h1><p class="lead">Add interests in your own words, simplify your personal context and find topics more easily.</p><div class="preview-status"><strong>Preview, not a published APK</strong><p>This candidate passed 841 local automated tests and release assembly. Candidate CI remains pending. Release signing and physical-phone acceptance are still pending. The official download remains 0.8.2; do not uninstall your existing app to try a file with an incompatible signature.</p><div class="actions"><a class="button" href="download.html">Get official 0.8.2</a><a class="button secondary" href="#changes">Explore 0.8.5 changes</a></div></div></section>
<section class="section wrap hairline" id="changes"><h2>Make MeBot yours with less setup</h2><div class="preview-guide"><article><span class="preview-number">01</span><div><h3>Your interests, in your words</h3><p>Onboarding lets you add custom interests as well as select topics. A live count helps you stay within <strong>150 words and 1,000 characters</strong>. Words are separated by whitespace, including Unicode whitespace. Both limits apply; the app does not silently shorten your text.</p><p>Your custom interests are saved with explicit topic scope. They are not automatically shared with every module.</p></div></article><article><span class="preview-number">02</span><div><h3>One place to introduce yourself</h3><p><strong>About you</strong> has one primary text area for your work, interests and what you want to follow. Write only what is useful. Optional Help shows an example in English or Kiswahili; it is not inserted or saved automatically.</p><p>Choose to insert an example yourself. If you already wrote something, confirm before replacing it. Your earlier individual context records remain intact under collapsed <strong>Saved details</strong>; simplifying the screen does not discard them.</p><p>Location, time zone and import/export options are grouped under <strong>Location, time zone &amp; transfer</strong>, while Save details stays prominent. Check your changes before saving.</p></div></article><article><span class="preview-number">03</span><div><h3>Find topics and saved reading more easily</h3><p>Modules uses a compact search field and horizontal filter rows, leaving more room for topics. Saved and Following have a clearer hierarchy: bookmarks keep reading, while stars follow stories. Manage follow-up timing in <strong>Saved → Following</strong>.</p><p>The price-comparison tool has been removed from 0.8.5. An older saved route to that tool returns safely to Modules. Other everyday tools remain available.</p></div></article></div></section>
<section class="section wrap hairline" lang="sw"><p class="eyebrow">Kwa kifupi</p><h2>Eleza unachopenda kwa maneno yako</h2><p>Ongeza unachopenda wakati wa kuanza, hadi maneno 150 na herufi 1,000. Hesabu inaonekana unapochapa; maandishi yako hayafupishwi kimya kimya. Kwenye Kuhusu wewe, tumia sehemu moja kueleza kazi, mambo unayopenda na unayotaka kufuatilia.</p><p>Mfano wa Usaidizi ni wa hiari. Unaamua kuuingiza, na utaombwa kuthibitisha kabla ya kubadilisha maandishi yaliyopo. Maelezo yako ya awali yanabaki kwenye sehemu ya maelezo yaliyohifadhiwa. Zana ya kulinganisha bei imeondolewa katika 0.8.5.</p><p>Upakuaji rasmi uliopo bado ni 0.8.2.</p></section>
<section class="section wrap hairline"><h2>Before a signed release</h2><p>The local gate passed 182 core, 490 Android and 169 service tests, with zero failures, errors or skips. Release assembly and ZIP alignment passed. Lint reported zero errors, 221 debug warnings, 222 release warnings and one hint per variant.</p><p>If the same production package uses a new signing certificate, it cannot update the old 0.8.2 installation in place. Export portable preferences before any owner-controlled reinstall; this does not promise that every kind of app data can be restored. MeBot will not automatically uninstall your existing app.</p><h2>What stays the same</h2><p>The icon-only star beside the bookmark, source-dependent fullscreen media, optional notifications and normal request allowances remain. Provider-supported controls do not guarantee that every video can play. Device speech input and installed-voice read-aloud are not full-duplex realtime voice.</p><p>Native captures use controlled example content. They show the interface, not live provider authorization, physical-phone installation, real streaming, notification delivery or overnight alarms.</p><div class="actions"><a class="button secondary" href="RELEASE-0.8.5.md">0.8.5 candidate notes</a><a class="text-link" href="preview-084.html">0.8.4 history →</a><a class="text-link" href="preview-083.html">0.8.3 history →</a><a class="text-link" href="guide.html">Official 0.8.2 guide →</a></div></section></main>'''
captures=[('interests','Your own interests','Native onboarding with custom-interest input and live limits; sample text.'),('about','A simpler About you','Native personal-context screen with a primary text area and optional settings; sample data.'),('modules','Find a topic','Native Modules screen with compact search and horizontal filters.'),('saved','Saved and Following','Native library hierarchy with controlled sample content.')]
figures=[]
for name,title,caption in captures:
    p=D/'screenshots/v085'/f'{name}.png'
    if not p.exists(): continue
    w,h=struct.unpack('>II',p.read_bytes()[16:24])
    figures.append(f'<figure class="shot"><a href="screenshots/v085/{name}.png" data-lightbox data-title="{title}" aria-label="Enlarge: {title}"><img src="screenshots/v085/{name}.png" width="{w}" height="{h}" loading="lazy" alt="{caption}"></a><figcaption><span class="shot-version">0.8.5 candidate · native render</span><strong>{title}</strong><span>{caption}</span></figcaption></figure>')
if figures:
    gallery='<section class="section wrap hairline"><h2>Native candidate preview</h2><div class="screen-grid">'+''.join(figures)+'</div><p class="micro"><a href="screenshots/v085/README.md">Capture provenance</a></p></section>'
    body=body.replace('<section class="section wrap hairline" id="changes">',gallery+'<section class="section wrap hairline" id="changes">')
(D/'preview-085.html').write_text(head+body+foot)
for p in [*D.glob('*.html'),*(D/'guides').glob('*.html')]:
    if p.name=='preview-085.html': continue
    t=re.sub(r'<!-- preview-08[345]:start -->.*?<!-- preview-08[345]:end -->','',p.read_text(),flags=re.S)
    rel='../' if p.parent.name=='guides' else ''
    banner=f'<!-- preview-085:start --><aside class="preview-banner"><strong>0.8.5 preview</strong> · Custom interests, simpler personal context and clearer navigation. <a href="{rel}preview-085.html">See changes and release status →</a></aside><!-- preview-085:end -->'
    p.write_text(t.replace('</header>','</header>'+banner,1))
for p,link in [(ROOT/'README.md','docs/RELEASE-0.8.5.md'),(ROOT/'START-HERE.md','docs/RELEASE-0.8.5.md'),(D/'USER-GUIDE.md','RELEASE-0.8.5.md')]:
    t=re.sub(r'<!-- preview-08[345]:start -->.*?<!-- preview-08[345]:end -->\n*','',p.read_text(),flags=re.S)
    p.write_text(f'<!-- preview-085:start -->\n> **0.8.5 candidate:** Custom interests, a simpler About you screen and clearer navigation; 841 local automated tests passed. [Current candidate guide]({link}). The official download remains **0.8.2**. Earlier candidate release notes are preserved as history.\n<!-- preview-085:end -->\n\n'+t)
print('Updated 0.8.5 current guidance; preserved prior candidate history and official 0.8.2 download.')
